  "inlineSchema": "datasource db {\n  provider = \"sqlite\"\n  url      = \"file:./dev.db\"\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\nmodel Tenant {\n  id        String   @id @default(uuid())\n  name      String\n  document  String   @unique // CNPJ ou similar\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  sectors   String   @default(\"[\\\"Administrativo\\\",\\\"Operacional\\\",\\\"Comercial\\\",\\\"TI\\\",\\\"RH\\\",\\\"Geral\\\"]\")\n\n  users       User[]\n  surveys     Survey[]\n  actionPlans ActionPlan[]\n\n  @@map(\"tenants\")\n}\n\nmodel User {\n  id       String  @id @default(uuid())\n  name     String\n  email    String  @unique\n  password String? // Opcional para quem usa SSO\n  ssoId    String? @unique // ID do Active Directory/SSO\n  role     String  @default(\"EMPLOYEE\")\n\n  tenantId String?\n  tenant   Tenant? @relation(fields: [tenantId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  actionPlans ActionPlan[] // Relacionamento inverso para Planos de Ação atribuídos a este usuário\n\n  @@map(\"users\")\n}\n\nmodel Survey {\n  id          String  @id @default(uuid())\n  title       String\n  description String?\n  isActive    Boolean @default(true)\n\n  tenantId String\n  tenant   Tenant @relation(fields: [tenantId], references: [id])\n\n  questions   Question[]\n  submissions Submission[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"surveys\")\n}\n\nmodel Question {\n  id       String @id @default(uuid())\n  surveyId String\n  survey   Survey @relation(fields: [surveyId], references: [id])\n  text     String\n\n  // Ex: \"PROBABILITY_IMPACT\", \"MULTIPLE_CHOICE\", \"TEXT\"\n  type String @default(\"PROBABILITY_IMPACT\")\n\n  answers Answer[]\n\n  @@map(\"questions\")\n}\n\n// Representa a participação de um colaborador em uma pesquisa\nmodel Submission {\n  id       String @id @default(uuid())\n  surveyId String\n  survey   Survey @relation(fields: [surveyId], references: [id])\n\n  // Anonimato (LGPD): Guarda apenas o Setor, sem identificar a pessoa\n  sector String? // Ex: \"TI\", \"RH\", \"Vendas\"\n\n  answers Answer[]\n\n  createdAt DateTime @default(now())\n\n  @@map(\"submissions\")\n}\n\n// Representa a resposta a uma pergunta específica\nmodel Answer {\n  id           String     @id @default(uuid())\n  submissionId String\n  submission   Submission @relation(fields: [submissionId], references: [id])\n  questionId   String\n  question     Question   @relation(fields: [questionId], references: [id])\n\n  // Valores para a matriz de risco (ex: 1 a 5)\n  probabilityScore Int?\n  impactScore      Int?\n\n  // Se for texto livre ou outro tipo\n  textValue String?\n\n  @@map(\"answers\")\n}\n\nmodel ActionPlan {\n  id          String   @id @default(uuid())\n  title       String\n  description String?\n  responsible String? // Nome em texto (legado ou para externos)\n  deadline    DateTime\n  status      String   @default(\"OPEN\")\n  sector      String?\n\n  assignedToId String?\n  assignedTo   User?   @relation(fields: [assignedToId], references: [id])\n\n  resolutionNotes String? // Observações de conclusão\n\n  tenantId String\n  tenant   Tenant @relation(fields: [tenantId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"action_plans\")\n}\n",
